changeSet.sql:
ALTER TABLE admin_user DROP CONSTRAINT ck_admin_user_password_hash_bcrypt;
ALTER TABLE admin_user
    ADD CONSTRAINT ck_admin_user_password_hash_bcrypt CHECK (
        CHAR_LENGTH(password_hash) = 60
        AND password_hash ~ '^[$]2[aby][$](0[4-9]|[12][0-9]|3[01])[$][./A-Za-z0-9]{53}$'
    );

rollback.sql:
